  { name:'Mars',    color:'#d1683d', glow:'rgba(209,104,61,.6)',r:5.8,dist:2.7,   period:687,   seed:5.5 },
  { name:'Jupiter', color:'#d3a276', glow:'rgba(211,162,118,.55)',r:17,dist:3.9,   period:4333,  seed:1.3, bands:true },
