const MAXD = Math.max(...PLANETS.map(p => p.dist));

function resize(){
  W = innerWidth; H = innerHeight;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = W*dpr; canvas.height = H*dpr;
  canvas.style.width = W+'px'; canvas.style.height = H+'px';
  ctx.setTransform(dpr,0,0,dpr,0,0);
  cx = W/2; cy = H/2;
  const M = Math.max(72, Math.min(W,H)*0.15);
  scale = Math.max(0.1, (Math.min(W,H)/2 - M) / BASE_R);
  buildStars();
}

function buildStars(){
  stars = [];
  const n = Math.round(W*H/6500);
  const hues = ['255,255,255','255,255,255','255,255,255','255,255,255','200,220,255','185,205,255','255,225,190','255,210,175'];
  for (let i=0;i<n;i++){
    const m = Math.random();
    stars.push({
      x: Math.random()*W, y: Math.random()*H,
      r: m<0.7 ? 0.4+Math.random()*0.5 : 0.5+Math.random()*1.1,
      base: 0.25+Math.random()*0.55,
      tw: 0.6+Math.random()*2.6,
      ph: Math.random()*TAU,
      c: hues[(Math.random()*hues.length)|0]
    });
